/* Practical, scripted travel rehearsal. Controller choices work without a microphone. */
const cafeLanguages={
'en-US':{greet:'Hello! What would you like?',order:'One coffee, please.',temp:'Hot or iced?',hot:'Hot, please.',where:'For here or to go?',here:'For here, please.',serve:'Here you are. Enjoy!',thanks:'Thank you.'},
'ja-JP':{greet:'いらっしゃいませ。ご注文は？',order:'コーヒーを一つください。',temp:'ホットですか、アイスですか？',hot:'ホットでお願いします。',where:'店内でお飲みですか、お持ち帰りですか？',here:'店内でお願いします。',serve:'どうぞ。ごゆっくり。',thanks:'ありがとうございます。'},
'fr-FR':{greet:'Bonjour ! Qu’est-ce que vous souhaitez ?',order:'Un café, s’il vous plaît.',temp:'Chaud ou glacé ?',hot:'Chaud, s’il vous plaît.',where:'Sur place ou à emporter ?',here:'Sur place, s’il vous plaît.',serve:'Voilà ! Bonne journée.',thanks:'Merci beaucoup.'},
'es-ES':{greet:'¡Hola! ¿Qué desea?',order:'Un café, por favor.',temp:'¿Caliente o con hielo?',hot:'Caliente, por favor.',where:'¿Para tomar aquí o para llevar?',here:'Para tomar aquí, por favor.',serve:'Aquí tiene. ¡Que lo disfrute!',thanks:'Muchas gracias.'},
'hi-IN':{greet:'नमस्ते! आप क्या लेना चाहेंगे?',order:'एक कॉफ़ी दीजिए, कृपया।',temp:'गरम या ठंडी?',hot:'गरम कॉफ़ी, कृपया।',where:'यहीं पीएँगे या साथ ले जाएँगे?',here:'यहीं, कृपया।',serve:'यह लीजिए। आनंद लें!',thanks:'धन्यवाद।'}};
let cafeAttempt=null;
function startCafe(){cafeAttempt={step:0,language:state.language,region:regions[state.region],hints:new Set(),mistakes:0,options:null,saved:false};openAdventure('cafe');say(cafeLanguages[state.language].greet)}
function cafeSteps(){const l=cafeLanguages[cafeAttempt.language];return[{prompt:l.greet,goal:'Politely order one coffee.',answer:l.order,meaning:'One coffee, please.'},{prompt:l.temp,goal:'Ask for a hot drink.',answer:l.hot,meaning:'Hot, please.'},{prompt:l.where,goal:'Say that you will drink it here.',answer:l.here,meaning:'For here, please.'},{prompt:l.serve,goal:'Thank the server.',answer:l.thanks,meaning:'Thank you.'}]}
function cafeScore(attempt){return Math.max(0,100-attempt.hints.size*15-attempt.mistakes*10)}
function cafeFeedback(attempt){if(!attempt.hints.size&&!attempt.mistakes)return'You completed all four replies without help.';return'You used '+attempt.hints.size+' hint'+(attempt.hints.size===1?'':'s')+' and '+attempt.mistakes+' retr'+(attempt.mistakes===1?'y':'ies')+'. Replay and try to use less help.'}
function finishCafe(){const a=cafeAttempt;if(a.saved)return;a.saved=true;const score=cafeScore(a),key='globiquest-cafe-'+a.region+'-'+a.language;let previous=null;try{previous=JSON.parse(localStorage.getItem(key)||'null');localStorage.setItem(key,JSON.stringify({score,best:Math.max(score,previous?.best||0),hints:a.hints.size,retries:a.mistakes,date:new Date().toISOString()}))}catch{}a.best=Math.max(score,previous?.best||0);adventure.award(a.region,'recalls',a.language+':cafe');window.globiquest.celebrate?.();showCafeCup(true)}
function renderCafe(){if(!cafeAttempt||cafeAttempt.language!==state.language){cafeAttempt={step:0,language:state.language,region:regions[state.region],hints:new Set(),mistakes:0,options:null,saved:false}}const a=cafeAttempt;if(a.step>=4){finishCafe();panel(featureRoot,{title:'Your order is complete! '+cafeScore(a)+' / 100',body:cafeFeedback(a),width:3.8,height:.73,y:.26,font:43});featureButton('Try again',-1,-.45,startCafe,1.65);featureButton('Paint a memory',1,-.45,()=>openAdventure('art'),1.65,true);panel(featureRoot,{title:'Best here: '+a.best+' / 100 · Progress is based on hints and retries.',width:3.8,height:.3,y:-.92,font:29,align:'center'});return}const step=cafeSteps()[a.step],hinted=a.hints.has(a.step);panel(featureRoot,{kicker:'CAFÉ REHEARSAL · '+(a.step+1)+' / 4',title:step.prompt,body:step.goal,width:3.8,height:.62,y:.35,font:43});featureButton('♫ Hear server',-.95,-.12,()=>say(step.prompt),1.7);featureButton(hinted?'Hint shown':'Show a hint',.95,-.12,()=>{a.hints.add(a.step);renderFeature()},1.7);if(!a.options){const distractors=[words[a.language][2][0],a.step===0?words[a.language][1][0]:cafeLanguages[a.language].order].filter(v=>v!==step.answer);if(distractors.length<2)distractors.push(words[a.language][0][0]);a.options=[step.answer,...distractors.slice(0,2)].sort(()=>Math.random()-.5)}a.options.forEach((answer,i)=>featureButton(answer,0,-.51-i*.29,()=>{if(answer!==step.answer){a.mistakes++;notify('That phrase does not complete this task. Try a different reply or use a hint.');return}say(answer);a.step++;a.options=null;renderFeature()},3.7,hinted&&answer===step.answer,.25));panel(featureRoot,{title:'Use the phrase you would say to the server. Hints highlight a useful reply.',width:3.8,height:.2,y:-1.29,font:24,align:'center'})}
function buildCafeModel(){if($('cafeModel'))return;const root=entity('a-entity',{id:'cafeModel',position:'0 .05 .4',visible:false},$('featureIsland'));playBox(root,0,.33,0,1.9,.6,.45,'#b69b7e');playBox(root,0,.66,0,2.03,.06,.55,'#e8ddc9');entity('a-cylinder',{radius:.13,height:.35,position:'-.62 .86 -.2',color:'#759a92'},root);entity('a-sphere',{radius:.11,position:'-.62 1.16 -.2',color:'#d9bd9b'},root);entity('a-cone',{'radius-bottom':.12,'radius-top':.09,height:.11,position:'-.62 1.29 -.2',color:'#f4eee1'},root);entity('a-sphere',{radius:.014,position:'-.655 1.18 -.1',color:'#465565'},root);entity('a-sphere',{radius:.014,position:'-.585 1.18 -.1',color:'#465565'},root);const cup=entity('a-entity',{id:'cafeCup',position:'.48 .78 .05',visible:false},root);entity('a-cylinder',{radius:.105,height:.17,color:'#f4f0e5'},cup);entity('a-torus',{radius:.055,'radius-tubular':.012,position:'.12 0 0',color:'#f4f0e5'},cup);entity('a-circle',{radius:.09,position:'0 .088 0',rotation:'-90 0 0',color:'#8b6b52'},cup)}
function showCafeCup(visible){if($('cafeCup'))$('cafeCup').setAttribute('visible',visible)}
window.globiquest.startCafe=startCafe;window.globiquest.cafePhrases=()=>cafeAttempt?.step>=4?cafeSteps().map(s=>s.answer+' — '+s.meaning):[];

window.globiquest.cafeLanguage=()=>cafeAttempt?.step>=4?cafeAttempt.language:state.language;
